layers.vertex:
attribute vec3 aO; attribute vec2 aT; attribute vec4 aH0, aH1, aH2, aH3; uniform float uTime;
    varying vec3 vN, vV, vL; varying float vU, vD; varying vec4 vH0, vH1, vH2, vH3;
    void main(){
      float u = uTime - aT.x; if (u < 0. || u > aT.y + 0.40){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 P = aO + position*vec3(6.00, 3.00, 6.00);
      vN = normalize(normal/vec3(1., 0.50, 1.)); vV = normalize(cameraPosition - P); vL = position; vU = u; vD = aT.y;
      vH0 = aH0; vH1 = aH1; vH2 = aH2; vH3 = aH3;
      gl_Position = projectionMatrix*viewMatrix*vec4(P, 1.);
    }

layers.fragment:
uniform vec3 uC, uB, uW; uniform float uTime; varying vec3 vN, vV, vL; varying float vU, vD; varying vec4 vH0, vH1, vH2, vH3;
    float h3(vec3 p){ return fract(sin(dot(p, vec3(127.1, 311.7, 74.7)))*43758.5453); }
  float vn(vec3 p){ vec3 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
    return mix(mix(mix(h3(i), h3(i + vec3(1,0,0)), f.x), mix(h3(i + vec3(0,1,0)), h3(i + vec3(1,1,0)), f.x), f.y),
               mix(mix(h3(i + vec3(0,0,1)), h3(i + vec3(1,0,1)), f.x), mix(h3(i + vec3(0,1,1)), h3(i + vec3(1,1,1)), f.x), f.y), f.z); }
    void main(){
      float grow = clamp(vU/0.20, 0., 1.);
      float formed = 1. - smoothstep(grow - .025, grow + .025, vL.y);                                               // rises from the ground
      float rise = exp(-pow((vL.y - grow)/.05, 2.))*(1. - step(1., grow));
      vec3 q = vL*3.2;
      float n = vn(q + vec3(0., uTime*.35, uTime*.12))*.65 + vn(q*2.3 - vec3(uTime*.2, 0., 0.))*.35;
      float vein = pow(1. - abs(2.*n - 1.), 7.);                                    // ridged noise: thin flowing plasma veins
      float fres = pow(1. - abs(dot(normalize(vN), normalize(vV))), 2.2);
      float foot = exp(-vL.y*vL.y/.0012);                                           // the limit itself, on the ground
      float endK = clamp((vU - vD)/0.40, 0., 1.), burn = 0., dissolve = 1.;
      if (endK > 0.){ float nd = vn(vL*6.); dissolve = 1. - smoothstep(nd - .045, nd + .045, endK*1.1); burn = exp(-pow((nd - endK*1.1)/.05, 2.)); }
      float pk = vU >= 0.20 && vU < 0.233 ? 1.4 : 1.;
      vec3 c = uB*(.004 + .02*fres) + uC*(fres*.075 + vein*(.009 + .065*fres) + foot*.32)   // low intensity: reads as a boundary, not a light source
             + uW*(vein*fres*.025 + rise*.25 + burn*.18);
      c *= pk*formed*dissolve;
      if (max(c.r, max(c.g, c.b)) < .002) discard;
      gl_FragColor = vec4(c, 1.);
    }
